    this.$('datalist').innerHTML = model.nodes.map(function (n) { return '<option value="' + escapeHtml(n.name) + '"></option>'; }).join('');
    this.palette = readPalette(this.root, model.categories.length);
    this.sprites = this.palette.cats.map(function (c) { return glowSprite(c, self.palette.dark); });
    this.foilSprite = glowSprite(this.palette.foil, this.palette.dark);
