      // Leave the overlays their room: the legend stands on the left of a
      // wide stage and along the bottom of a narrow one.
      var m = this.overlayMargins(pad);
      var availW = this.W - m.left - m.right, availH = this.H - m.top - m.bottom;
      var k = Math.min(availW / Math.max(1, maxX - minX), availH / Math.max(1, maxY - minY));
      k = clamp(k, 0.2, nodes ? 1.6 : 2.2);
