          for (var i = 1; i < arr.length; i++) { if (arr[i].y - arr[i - 1].y < gap) { arr[i].y = arr[i - 1].y + gap; } }
          for (i = arr.length - 2; i >= 0; i--) { if (arr[i + 1].y - arr[i].y < gap) { arr[i].y = arr[i + 1].y - gap; } }
